--
-- Table structure for table `es_exhibitions`
--

DROP TABLE IF EXISTS `es_exhibitions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `es_exhibitions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `location_id` int(11) DEFAULT NULL,
  `event_organizer` int(11) DEFAULT NULL,
  `exhibition_title` varchar(255) DEFAULT NULL,
  `booking_expire_date` date DEFAULT NULL,
  `price_type` enum('USD','PKR') DEFAULT 'PKR',
  `event_color` varchar(50) DEFAULT NULL,
  `event_background` text DEFAULT NULL,
  `event_logo` text DEFAULT NULL,
  `event_logo_link` text DEFAULT NULL,
  `associate_logo` text DEFAULT NULL,
  `associate_logo_link` text DEFAULT NULL,
  `manager_logo` text DEFAULT NULL,
  `manager_logo_link` text DEFAULT NULL,
  `event_updates` text DEFAULT NULL COMMENT 'not in use',
  `disclaimer` text DEFAULT NULL COMMENT 'not in use',
  `company_address` text DEFAULT NULL COMMENT 'not in use',
  `dashboard_content` text DEFAULT NULL COMMENT 'not in use',
  `stall_builder_contractors` text DEFAULT NULL,
  `is_completed` tinyint(1) DEFAULT 0,
  `created_on` datetime DEFAULT NULL,
  `is_deleted` tinyint(1) DEFAULT 0,
  `deleted_by` int(11) DEFAULT NULL,
  `deleted_on` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `exhibition_location` (`location_id`),
  KEY `event_organizer` (`event_organizer`),
  CONSTRAINT `es_exhibitions_ibfk_1` FOREIGN KEY (`location_id`) REFERENCES `es_locations` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `es_exhibitions_ibfk_2` FOREIGN KEY (`event_organizer`) REFERENCES `es_organizer` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `es_exhibitions`
--

LOCK TABLES `es_exhibitions` WRITE;
/*!40000 ALTER TABLE `es_exhibitions` DISABLE KEYS */;
