--
-- Table structure for table `es_inventory_item`
--

DROP TABLE IF EXISTS `es_inventory_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `es_inventory_item` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `exhibition_id` int(11) DEFAULT NULL,
  `category_id` int(11) DEFAULT NULL,
  `global_item_id` int(11) DEFAULT NULL,
  `item_title` varchar(255) DEFAULT NULL,
  `item_image` text DEFAULT NULL,
  `item_stock` double DEFAULT 0,
  `item_price_usd` double DEFAULT 0,
  `item_price_pkr` double DEFAULT 0,
  `is_active` tinyint(1) DEFAULT 1,
  `created_on` datetime DEFAULT NULL,
  `is_deleted` tinyint(1) DEFAULT 0,
  `deleted_by` int(11) DEFAULT NULL,
  `deleted_on` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `category_id` (`category_id`),
  KEY `exhibition_id` (`exhibition_id`),
  KEY `global_item_id` (`global_item_id`),
  CONSTRAINT `es_inventory_item_ibfk_1` FOREIGN KEY (`category_id`) REFERENCES `es_inventory_category` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `es_inventory_item_ibfk_2` FOREIGN KEY (`exhibition_id`) REFERENCES `es_exhibitions` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `es_inventory_item_ibfk_3` FOREIGN KEY (`global_item_id`) REFERENCES `es_inventory_item_global` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=93 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

